package com.trampolim.api.career;
import java.util.*;import java.time.*;import static com.trampolim.api.radar.RadarModel.*;import com.trampolim.api.radar.*;import org.springframework.web.bind.annotation.*;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.transaction.annotation.Transactional;import org.springframework.http.HttpStatus;import org.springframework.web.server.ResponseStatusException;
@RestController @RequestMapping("/api/career")
public class CareerProjectsController {
 private final JdbcTemplate jdbc;private final SkillCatalog users;private final RadarBridge bridge;
 public CareerProjectsController(@Qualifier("jdbcTemplate")JdbcTemplate jdbc,SkillCatalog users,RadarBridge bridge){this.jdbc=jdbc;this.users=users;this.bridge=bridge;}
 public record Submit(UUID receiptId,long challengeId,String alias,String body,String projectUrl,boolean consent){}
 public record Item(String kind,String title,String description,String url,UUID submissionReceipt){}
 @GetMapping("/challenges")public Map<String,Object> challenges(@AuthenticationPrincipal String email,@RequestParam(defaultValue="9223372036854775807")long before,@RequestParam(defaultValue="20")int limit,@RequestParam(defaultValue="")String region){users.user(email);CareerRules.page(before,limit);return bridge.convert(bridge.get("/public/career/challenges?before="+before+"&limit="+limit+"&region="+CareerRules.region(region,true)),Map.class);}
 @GetMapping("/challenges/{id}")public Map<String,Object> challenge(@AuthenticationPrincipal String email,@PathVariable long id){users.user(email);return bridge.convert(bridge.get("/public/career/challenges/"+id),Map.class);}
 @PostMapping("/challenges/submissions")@Transactional("oportunidadesTransactionManager")public Map<String,Object> submit(@AuthenticationPrincipal String email,@RequestBody Submit input){long uid=users.user(email);if(input==null||input.receiptId()==null||input.challengeId()<1||!input.consent()||text(input.alias(),80).isEmpty()||text(input.body(),12000).length()<20)bad("Informe uma identificação escolhida, projeto e confirme as condições de envio para esta empresa.");String alias=input.alias().trim(),body=input.body().trim(),url=CareerRules.https(input.projectUrl());String hash=RadarBridge.hash(bridge.encode(List.of(input.challengeId(),alias,body,url)));jdbc.queryForObject("SELECT id FROM app_users WHERE id=? FOR UPDATE",Long.class,uid);var prior=jdbc.queryForList("SELECT receipt_id,request_hash,withdrawn_at FROM career_challenge_submissions WHERE user_id=? AND challenge_id=?",uid,input.challengeId());if(!prior.isEmpty()){var p=prior.get(0);if(!p.get("receipt_id").equals(input.receiptId())||!p.get("request_hash").equals(hash)||p.get("withdrawn_at")!=null)throw new ResponseStatusException(HttpStatus.CONFLICT,"Já existe entrega para este desafio ou ela foi retirada.");return Map.of("receiptId",p.get("receipt_id"),"status","ALREADY_REGISTERED");}bridge.get("/public/career/challenges/"+input.challengeId());if(jdbc.queryForObject("SELECT count(*) FROM career_challenge_submissions WHERE user_id=? AND withdrawn_at IS NULL",Integer.class,uid)>=50)bad("Limite de cinquenta entregas ativas atingido.");Instant consent=Instant.now();jdbc.update("INSERT INTO career_challenge_submissions(receipt_id,user_id,challenge_id,alias,body,project_url,request_hash,consent_at) VALUES (?,?,?,?,?,?,?,?)",input.receiptId(),uid,input.challengeId(),alias,body,url,hash,java.sql.Timestamp.from(consent));var delivery=new CompanyCareerService.Delivery(1,input.receiptId(),input.challengeId(),alias,body,url,hash,consent);jdbc.update("INSERT INTO career_delivery_jobs(id,owner_user_id,receipt_id,event_kind,payload) VALUES (?,?,?,'SUBMIT',?::jsonb)",UUID.randomUUID(),uid,input.receiptId(),bridge.encode(delivery));return Map.of("receiptId",input.receiptId(),"status","PENDING_DELIVERY");}
 @GetMapping("/challenges/submissions/mine")public List<Map<String,Object>> mine(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT s.receipt_id,s.challenge_id,s.alias,s.body,s.project_url,s.consent_at,s.withdrawn_at,j.status AS delivery_status FROM career_challenge_submissions s LEFT JOIN career_delivery_jobs j ON j.receipt_id=s.receipt_id AND j.event_kind='SUBMIT' WHERE s.user_id=? ORDER BY s.consent_at DESC LIMIT 100",users.user(email));}
 @GetMapping("/challenges/submissions/{receipt}")public Map<String,Object> review(@AuthenticationPrincipal String email,@PathVariable UUID receipt){long uid=users.user(email);if(!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM career_challenge_submissions WHERE receipt_id=? AND user_id=?)",Boolean.class,receipt,uid)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);return bridge.convert(bridge.post("/integrations/career/challenges/receipt",new CompanyCareerService.Receipt(1,receipt)),Map.class);}
 @DeleteMapping("/challenges/submissions/{receipt}")@ResponseStatus(HttpStatus.NO_CONTENT)@Transactional("oportunidadesTransactionManager")public void withdraw(@AuthenticationPrincipal String email,@PathVariable UUID receipt){long uid=users.user(email);if(jdbc.update("UPDATE career_challenge_submissions SET withdrawn_at=COALESCE(withdrawn_at,CURRENT_TIMESTAMP),alias='',body='',project_url='' WHERE receipt_id=? AND user_id=?",receipt,uid)==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);jdbc.update("UPDATE career_delivery_jobs SET status='REJECTED',payload='{}' WHERE receipt_id=? AND event_kind='SUBMIT'",receipt);jdbc.update("INSERT INTO career_delivery_jobs(id,owner_user_id,receipt_id,event_kind,payload) VALUES (?,?,?,'WITHDRAW',?::jsonb) ON CONFLICT(receipt_id,event_kind) DO NOTHING",UUID.randomUUID(),uid,receipt,bridge.encode(new CompanyCareerService.Receipt(1,receipt)));}
 @GetMapping("/portfolio/items")public List<Map<String,Object>> items(@AuthenticationPrincipal String email){return jdbc.queryForList("SELECT id,kind,title,description,url,submission_receipt,created_at FROM career_portfolio_items WHERE user_id=? ORDER BY created_at DESC LIMIT 100",users.user(email));}
 @PostMapping("/portfolio/items")public Map<String,Object> item(@AuthenticationPrincipal String email,@RequestBody Item input){long uid=users.user(email);if(input==null||!Set.of("PROJECT","EXPERIENCE","COURSE","CHALLENGE").contains(Objects.toString(input.kind(),""))||text(input.title(),180).isEmpty()||text(input.description(),4000).isEmpty())bad("Informe tipo, título e descrição; experiências e cursos manuais são declarados.");if(input.kind().equals("CHALLENGE")){if(input.submissionReceipt()==null||!Boolean.TRUE.equals(jdbc.queryForObject("SELECT EXISTS(SELECT 1 FROM career_challenge_submissions WHERE receipt_id=? AND user_id=? AND withdrawn_at IS NULL)",Boolean.class,input.submissionReceipt(),uid)))throw new ResponseStatusException(HttpStatus.NOT_FOUND);}else if(input.submissionReceipt()!=null)bad("Referência de desafio incompatível.");if(jdbc.queryForObject("SELECT count(*) FROM career_portfolio_items WHERE user_id=?",Integer.class,uid)>=100)bad("Limite de cem itens atingido.");UUID id=UUID.randomUUID();jdbc.update("INSERT INTO career_portfolio_items(id,user_id,kind,title,description,url,submission_receipt) VALUES (?,?,?,?,?,?,?)",id,uid,input.kind(),input.title().trim(),input.description().trim(),CareerRules.https(input.url()),input.submissionReceipt());return Map.of("id",id,"origin",input.kind().equals("CHALLENGE")?"CHALLENGE_REFERENCE":"DECLARED");}
 @DeleteMapping("/portfolio/items/{id}")@ResponseStatus(HttpStatus.NO_CONTENT)public void delete(@AuthenticationPrincipal String email,@PathVariable UUID id){if(jdbc.update("DELETE FROM career_portfolio_items WHERE id=? AND user_id=?",id,users.user(email))==0)throw new ResponseStatusException(HttpStatus.NOT_FOUND);}
}
